-- Spark Feedback: every question as stored in Strapi (schema strapi): texts in en/ms/zh/ta, branches, order, published state.
-- Exported 2026-11-17. It EMPTIES the question tables first, then loads them.
-- Restore on another machine: 1) start the API stack, 2) start Strapi once so it creates its tables,
--   3) docker exec -i spark_feedback_postgres psql -U spark -d spark < sql/strapi_questions.sql
--   4) docker restart spark_feedback_strapi
BEGIN;
TRUNCATE strapi.questions_cmps, strapi.questions_questionnaire_lnk, strapi.components_flow_branches, strapi.components_shared_texts, strapi.questions, strapi.questionnaires RESTART IDENTITY;
\restrict Icnjm6oILpex5CuDPkk1t3lDNcTi3skfg02TeVFkoqSYeGlh3L7VCiebOxwTDPz
SELECT pg_catalog.setval('strapi.components_flow_branches_id_seq', 140, true);
SELECT pg_catalog.setval('strapi.components_shared_texts_id_seq', 596, true);
SELECT pg_catalog.setval('strapi.questionnaires_id_seq', 16, true);
SELECT pg_catalog.setval('strapi.questions_cmps_id_seq', 724, true);
SELECT pg_catalog.setval('strapi.questions_id_seq', 143, true);
SELECT pg_catalog.setval('strapi.questions_questionnaire_lnk_id_seq', 245, true);
\unrestrict Icnjm6oILpex5CuDPkk1t3lDNcTi3skfg02TeVFkoqSYeGlh3L7VCiebOxwTDPz
SELECT setval(pg_get_serial_sequence('strapi.questionnaires','id'), COALESCE((SELECT max(id) FROM strapi.questionnaires),1));
SELECT setval(pg_get_serial_sequence('strapi.questions','id'), COALESCE((SELECT max(id) FROM strapi.questions),1));
SELECT setval(pg_get_serial_sequence('strapi.components_shared_texts','id'), COALESCE((SELECT max(id) FROM strapi.components_shared_texts),1));
SELECT setval(pg_get_serial_sequence('strapi.components_flow_branches','id'), COALESCE((SELECT max(id) FROM strapi.components_flow_branches),1));
SELECT setval(pg_get_serial_sequence('strapi.questions_cmps','id'), COALESCE((SELECT max(id) FROM strapi.questions_cmps),1));
SELECT setval(pg_get_serial_sequence('strapi.questions_questionnaire_lnk','id'), COALESCE((SELECT max(id) FROM strapi.questions_questionnaire_lnk),1));
COMMIT;
