INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (249, 'en', 'May I know if you have purchased the policy through door-knock?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (250, 'ms', 'Boleh saya tahu sama ada anda membeli polisi ini melalui jualan dari pintu ke pintu (door-knock)?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (251, 'zh', '请问您是通过上门推销（敲门拜访）购买这份保单的吗？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (252, 'ta', 'நீங்கள் இந்தப் பாலிசியை வீடு வீடாகச் சென்று செய்யும் விற்பனை (door-knock) மூலம் வாங்கினீர்களா என்று நான் தெரிந்துகொள்ளலாமா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (253, 'en', 'May I know if you have purchased the policy through door-knock?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (254, 'ms', 'Boleh saya tahu sama ada anda membeli polisi ini melalui jualan dari pintu ke pintu (door-knock)?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (255, 'zh', '请问您是通过上门推销（敲门拜访）购买这份保单的吗？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (256, 'ta', 'நீங்கள் இந்தப் பாலிசியை வீடு வீடாகச் சென்று செய்யும் விற்பனை (door-knock) மூலம் வாங்கினீர்களா என்று நான் தெரிந்துகொள்ளலாமா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (356, 'ta', 'பொருத்தமான தயாரிப்பு பரிந்துரைக்கப்படுவதற்கு முன், உங்கள் நிதி நிலைமை, தற்போதைய நிதித் திட்டங்கள், முன்னுரிமைகள் மற்றும் இடர் சுயவிவரம் பற்றி உங்களுடன் பேசப்பட்டதா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (357, 'en', 'Were your financial situation, current financial plans, priorities and risk profile discussed with you before a suitable product was recommended?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (358, 'ms', 'Adakah keadaan kewangan, pelan kewangan semasa, keutamaan dan profil risiko anda dibincangkan dengan anda sebelum produk yang sesuai disyorkan?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (359, 'zh', '在向您推荐合适的产品之前，是否已与您讨论过您的财务状况、目前的财务规划、优先事项和风险属性？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (360, 'ta', 'பொருத்தமான தயாரிப்பு பரிந்துரைக்கப்படுவதற்கு முன், உங்கள் நிதி நிலைமை, தற்போதைய நிதித் திட்டங்கள், முன்னுரிமைகள் மற்றும் இடர் சுயவிவரம் பற்றி உங்களுடன் பேசப்பட்டதா?');
