INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (393, 'en', 'Did your agent discuss with you the type of funds you can use to cover the premiums for the full premium term?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (394, 'ms', 'Adakah ejen anda berbincang dengan anda tentang jenis dana yang boleh anda gunakan untuk membayar premium bagi seluruh tempoh premium?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (395, 'zh', '您的代理人是否与您讨论过，在整个缴费期内可用于支付保费的资金类型？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (396, 'ta', 'முழு பிரீமியக் காலத்திற்கும் பிரீமியங்களைச் செலுத்த நீங்கள் பயன்படுத்தக்கூடிய நிதி வகைகள் பற்றி உங்கள் முகவர் உங்களுடன் பேசினாரா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (397, 'en', 'Did your agent discuss with you the type of funds you can use to cover the premiums for the full premium term?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (398, 'ms', 'Adakah ejen anda berbincang dengan anda tentang jenis dana yang boleh anda gunakan untuk membayar premium bagi seluruh tempoh premium?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (399, 'zh', '您的代理人是否与您讨论过，在整个缴费期内可用于支付保费的资金类型？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (476, 'ta', 'இந்த நிறுத்தம் பற்றி உங்கள் முகவருக்குத் தெரிவிக்கப்பட்டதா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (477, 'en', 'Was your agent informed of this termination?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (478, 'ms', 'Adakah ejen anda dimaklumkan tentang penamatan ini?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (479, 'zh', '您的代理人是否已被告知这次终止？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (480, 'ta', 'இந்த நிறுத்தம் பற்றி உங்கள் முகவருக்குத் தெரிவிக்கப்பட்டதா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (481, 'en', 'Can I know which insurance company or bank you purchased the previous policy from?');
