INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (257, 'en', 'Would you be comfortable for this call to be conducted in English?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (258, 'ms', 'Adakah anda selesa jika panggilan ini dijalankan dalam Bahasa Inggeris?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (259, 'zh', '您是否方便用英语进行这次通话？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (260, 'ta', 'இந்த அழைப்பை ஆங்கிலத்தில் நடத்துவது உங்களுக்கு வசதியாக இருக்குமா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (261, 'en', 'Which language would you prefer for this call: Mandarin, Bahasa Malay or Tamil?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (262, 'ms', 'Bahasa manakah yang anda lebih suka untuk panggilan ini: Mandarin, Bahasa Melayu atau Tamil?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (263, 'zh', '您希望用哪种语言进行这次通话：华语、马来语还是淡米尔语？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (264, 'ta', 'இந்த அழைப்புக்கு எந்த மொழியை விரும்புகிறீர்கள்: மாண்டரின், மலாய் அல்லது தமிழ்?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (400, 'ta', 'முழு பிரீமியக் காலத்திற்கும் பிரீமியங்களைச் செலுத்த நீங்கள் பயன்படுத்தக்கூடிய நிதி வகைகள் பற்றி உங்கள் முகவர் உங்களுடன் பேசினாரா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (401, 'en', 'Was the information you shared with the agent in the discussion documented accurately?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (402, 'ms', 'Adakah maklumat yang anda kongsikan dengan ejen semasa perbincangan didokumenkan dengan tepat?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (403, 'zh', '您在讨论中向代理人提供的资料，是否已被准确记录？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (404, 'ta', 'கலந்துரையாடலில் நீங்கள் முகவருடன் பகிர்ந்த தகவல்கள் துல்லியமாகப் பதிவு செய்யப்பட்டனவா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (405, 'en', 'Was the information you shared with the agent in the discussion documented accurately?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (406, 'ms', 'Adakah maklumat yang anda kongsikan dengan ejen semasa perbincangan didokumenkan dengan tepat?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (407, 'zh', '您在讨论中向代理人提供的资料，是否已被准确记录？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (408, 'ta', 'கலந்துரையாடலில் நீங்கள் முகவருடன் பகிர்ந்த தகவல்கள் துல்லியமாகப் பதிவு செய்யப்பட்டனவா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (409, 'en', 'Can I know which portion or portions of the sales document are not accurate?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (410, 'ms', 'Boleh saya tahu bahagian mana dalam dokumen jualan yang tidak tepat?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (411, 'zh', '请问销售文件中的哪些部分不准确？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (412, 'ta', 'விற்பனை ஆவணத்தின் எந்தப் பகுதி அல்லது பகுதிகள் துல்லியமற்றவை என்று நான் தெரிந்துகொள்ளலாமா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (413, 'en', 'Can I know which portion or portions of the sales document are not accurate?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (414, 'ms', 'Boleh saya tahu bahagian mana dalam dokumen jualan yang tidak tepat?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (415, 'zh', '请问销售文件中的哪些部分不准确？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (416, 'ta', 'விற்பனை ஆவணத்தின் எந்தப் பகுதி அல்லது பகுதிகள் துல்லியமற்றவை என்று நான் தெரிந்துகொள்ளலாமா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (417, 'en', 'Were the following features of the policy explained: name or type of policy, premium amount, policy term and free look period?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (418, 'ms', 'Adakah ciri-ciri polisi berikut dijelaskan: nama atau jenis polisi, jumlah premium, tempoh polisi dan tempoh pertimbangan (free look)?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (419, 'zh', '保单的以下特点是否已向您说明：保单名称或类型、保费金额、保单期限和审阅期（free look）？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (420, 'ta', 'பாலிசியின் பின்வரும் அம்சங்கள் விளக்கப்பட்டனவா: பாலிசியின் பெயர் அல்லது வகை, பிரீமியத் தொகை, பாலிசிக் காலம் மற்றும் மறுபரிசீலனைக் காலம் (free look)?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (421, 'en', 'Were the following features of the policy explained: name or type of policy, premium amount, policy term and free look period?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (422, 'ms', 'Adakah ciri-ciri polisi berikut dijelaskan: nama atau jenis polisi, jumlah premium, tempoh polisi dan tempoh pertimbangan (free look)?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (423, 'zh', '保单的以下特点是否已向您说明：保单名称或类型、保费金额、保单期限和审阅期（free look）？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (424, 'ta', 'பாலிசியின் பின்வரும் அம்சங்கள் விளக்கப்பட்டனவா: பாலிசியின் பெயர் அல்லது வகை, பிரீமியத் தொகை, பாலிசிக் காலம் மற்றும் மறுபரிசீலனைக் காலம் (free look)?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (425, 'en', 'Were the benefits of the policy, the disadvantages of early surrender or not paying premiums, and the investment risk, fees and charges explained?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (426, 'ms', 'Adakah manfaat polisi, keburukan penyerahan awal atau tidak membayar premium, serta risiko pelaburan, yuran dan caj dijelaskan?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (427, 'zh', '保单的保障、提前退保或不缴付保费的不利之处，以及投资风险、费用和收费，是否已向您说明？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (428, 'ta', 'பாலிசியின் பலன்கள், முன்கூட்டியே சரணடைவதன் அல்லது பிரீமியம் செலுத்தாததன் தீமைகள், மற்றும் முதலீட்டு இடர், கட்டணங்கள் ஆகியவை விளக்கப்பட்டனவா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (429, 'en', 'Were the benefits of the policy, the disadvantages of early surrender or not paying premiums, and the investment risk, fees and charges explained?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (430, 'ms', 'Adakah manfaat polisi, keburukan penyerahan awal atau tidak membayar premium, serta risiko pelaburan, yuran dan caj dijelaskan?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (431, 'zh', '保单的保障、提前退保或不缴付保费的不利之处，以及投资风险、费用和收费，是否已向您说明？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (225, 'en', 'Are you familiar with, or do you know the name of, your agent?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (226, 'ms', 'Adakah anda mengenali, atau tahu nama ejen anda?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (227, 'zh', '您是否认识您的代理人，或知道代理人的姓名？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (228, 'ta', 'உங்கள் முகவரை உங்களுக்குத் தெரியுமா, அல்லது அவரது பெயர் தெரியுமா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (265, 'en', 'Was your agent and his/her manager present at the sales meeting together with you?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (266, 'ms', 'Adakah ejen anda dan pengurusnya hadir bersama anda semasa mesyuarat jualan?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (267, 'zh', '您的代理人及其经理是否都与您一起出席了销售会面？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (268, 'ta', 'உங்கள் முகவரும் அவரது மேலாளரும் விற்பனைச் சந்திப்பில் உங்களுடன் சேர்ந்து இருந்தார்களா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (273, 'en', 'Can I know who is not present? Agent or Manager?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (274, 'ms', 'Boleh saya tahu siapa yang tidak hadir? Ejen atau Pengurus?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (275, 'zh', '请问谁没有出席？是代理人还是经理？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (276, 'ta', 'யார் இல்லை என்று நான் தெரிந்துகொள்ளலாமா? முகவரா அல்லது மேலாளரா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (432, 'ta', 'பாலிசியின் பலன்கள், முன்கூட்டியே சரணடைவதன் அல்லது பிரீமியம் செலுத்தாததன் தீமைகள், மற்றும் முதலீட்டு இடர், கட்டணங்கள் ஆகியவை விளக்கப்பட்டனவா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (433, 'en', 'Did your agent highlight the risk of insufficient funds, leading to penalties such as lapsation of premiums or loss of coverage?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (434, 'ms', 'Adakah ejen anda menekankan risiko dana yang tidak mencukupi, yang boleh menyebabkan penalti seperti lupusnya premium atau kehilangan perlindungan?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (435, 'zh', '您的代理人是否强调过资金不足的风险，可能导致保费失效或失去保障等处罚？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (436, 'ta', 'போதிய நிதி இல்லாததால் பிரீமியங்கள் காலாவதியாதல் அல்லது காப்பீட்டுப் பாதுகாப்பை இழத்தல் போன்ற அபராதங்கள் ஏற்படும் இடர் குறித்து உங்கள் முகவர் எடுத்துக்காட்டினாரா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (437, 'en', 'Did your agent highlight the risk of insufficient funds, leading to penalties such as lapsation of premiums or loss of coverage?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (438, 'ms', 'Adakah ejen anda menekankan risiko dana yang tidak mencukupi, yang boleh menyebabkan penalti seperti lupusnya premium atau kehilangan perlindungan?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (439, 'zh', '您的代理人是否强调过资金不足的风险，可能导致保费失效或失去保障等处罚？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (440, 'ta', 'போதிய நிதி இல்லாததால் பிரீமியங்கள் காலாவதியாதல் அல்லது காப்பீட்டுப் பாதுகாப்பை இழத்தல் போன்ற அபராதங்கள் ஏற்படும் இடர் குறித்து உங்கள் முகவர் எடுத்துக்காட்டினாரா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (441, 'en', 'Did your agent explain the importance of premium sustainability and the recommended funding required if your budget is fully utilized?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (442, 'ms', 'Adakah ejen anda menerangkan kepentingan kemampanan premium dan pembiayaan disyorkan yang diperlukan jika bajet anda telah digunakan sepenuhnya?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (443, 'zh', '您的代理人是否说明过保费可持续性的重要性，以及在您的预算已完全用尽的情况下所建议的资金安排？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (444, 'ta', 'பிரீமியத்தைத் தொடர்ந்து செலுத்தும் திறனின் முக்கியத்துவத்தையும், உங்கள் பட்ஜெட் முழுமையாகப் பயன்படுத்தப்பட்டால் தேவைப்படும் பரிந்துரைக்கப்பட்ட நிதியையும் உங்கள் முகவர் விளக்கினாரா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (445, 'en', 'Did your agent explain the importance of premium sustainability and the recommended funding required if your budget is fully utilized?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (446, 'ms', 'Adakah ejen anda menerangkan kepentingan kemampanan premium dan pembiayaan disyorkan yang diperlukan jika bajet anda telah digunakan sepenuhnya?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (447, 'zh', '您的代理人是否说明过保费可持续性的重要性，以及在您的预算已完全用尽的情况下所建议的资金安排？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (448, 'ta', 'பிரீமியத்தைத் தொடர்ந்து செலுத்தும் திறனின் முக்கியத்துவத்தையும், உங்கள் பட்ஜெட் முழுமையாகப் பயன்படுத்தப்பட்டால் தேவைப்படும் பரிந்துரைக்கப்பட்ட நிதியையும் உங்கள் முகவர் விளக்கினாரா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (449, 'en', 'Did the policy you purchased meet your needs?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (450, 'ms', 'Adakah polisi yang anda beli memenuhi keperluan anda?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (451, 'zh', '您购买的保单是否符合您的需求？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (452, 'ta', 'நீங்கள் வாங்கிய பாலிசி உங்கள் தேவைகளைப் பூர்த்தி செய்ததா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (453, 'en', 'Did the policy you purchased meet your needs?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (454, 'ms', 'Adakah polisi yang anda beli memenuhi keperluan anda?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (455, 'zh', '您购买的保单是否符合您的需求？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (229, 'en', 'Are you familiar with, or do you know the name of, your agent?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (230, 'ms', 'Adakah anda mengenali, atau tahu nama ejen anda?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (231, 'zh', '您是否认识您的代理人，或知道代理人的姓名？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (232, 'ta', 'உங்கள் முகவரை உங்களுக்குத் தெரியுமா, அல்லது அவரது பெயர் தெரியுமா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (281, 'en', 'Did your Agent''s manager call you after the sales meeting?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (282, 'ms', 'Adakah pengurus ejen anda menghubungi anda selepas mesyuarat jualan?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (283, 'zh', '销售会面之后，您代理人的经理是否曾致电给您？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (284, 'ta', 'விற்பனைச் சந்திப்புக்குப் பிறகு உங்கள் முகவரின் மேலாளர் உங்களை அழைத்தாரா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (285, 'en', 'Did your Agent''s manager call you after the sales meeting?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (286, 'ms', 'Adakah pengurus ejen anda menghubungi anda selepas mesyuarat jualan?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (287, 'zh', '销售会面之后，您代理人的经理是否曾致电给您？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (288, 'ta', 'விற்பனைச் சந்திப்புக்குப் பிறகு உங்கள் முகவரின் மேலாளர் உங்களை அழைத்தாரா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (289, 'en', 'Did your agent inform you that you can have a trusted individual to accompany you for the sales appointment?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (290, 'ms', 'Adakah ejen anda memaklumkan bahawa anda boleh ditemani oleh individu dipercayai semasa temu janji jualan?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (291, 'zh', '您的代理人是否告知您，可以由一位可信赖的人士陪同您参加销售会面？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (292, 'ta', 'விற்பனைச் சந்திப்பின்போது நம்பகமான ஒருவர் உங்களுடன் வரலாம் என்று உங்கள் முகவர் தெரிவித்தாரா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (293, 'en', 'Did your agent inform you that you can have a trusted individual to accompany you for the sales appointment?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (294, 'ms', 'Adakah ejen anda memaklumkan bahawa anda boleh ditemani oleh individu dipercayai semasa temu janji jualan?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (295, 'zh', '您的代理人是否告知您，可以由一位可信赖的人士陪同您参加销售会面？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (296, 'ta', 'விற்பனைச் சந்திப்பின்போது நம்பகமான ஒருவர் உங்களுடன் வரலாம் என்று உங்கள் முகவர் தெரிவித்தாரா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (297, 'en', 'Were you accompanied by a trusted individual?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (298, 'ms', 'Adakah anda ditemani oleh individu dipercayai?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (299, 'zh', '是否有可信赖的人士陪同您？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (300, 'ta', 'நம்பகமான ஒருவர் உங்களுடன் வந்திருந்தாரா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (301, 'en', 'Were you accompanied by a trusted individual?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (302, 'ms', 'Adakah anda ditemani oleh individu dipercayai?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (303, 'zh', '是否有可信赖的人士陪同您？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (304, 'ta', 'நம்பகமான ஒருவர் உங்களுடன் வந்திருந்தாரா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (305, 'en', 'Was your agent''s manager at the sales meeting together with you?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (306, 'ms', 'Adakah pengurus ejen anda hadir bersama anda semasa mesyuarat jualan?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (307, 'zh', '您代理人的经理是否与您一起出席了销售会面？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (308, 'ta', 'உங்கள் முகவரின் மேலாளர் விற்பனைச் சந்திப்பில் உங்களுடன் இருந்தாரா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (309, 'en', 'Was your agent''s manager at the sales meeting together with you?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (310, 'ms', 'Adakah pengurus ejen anda hadir bersama anda semasa mesyuarat jualan?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (311, 'zh', '您代理人的经理是否与您一起出席了销售会面？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (312, 'ta', 'உங்கள் முகவரின் மேலாளர் விற்பனைச் சந்திப்பில் உங்களுடன் இருந்தாரா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (456, 'ta', 'நீங்கள் வாங்கிய பாலிசி உங்கள் தேவைகளைப் பூர்த்தி செய்ததா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (457, 'en', 'Are you happy to keep the policy even though it is not suitable for you?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (458, 'ms', 'Adakah anda gembira untuk mengekalkan polisi ini walaupun ia tidak sesuai untuk anda?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (459, 'zh', '即使这份保单不适合您，您是否仍愿意保留它？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (460, 'ta', 'இந்தப் பாலிசி உங்களுக்குப் பொருத்தமாக இல்லாவிட்டாலும் அதை வைத்துக்கொள்ள நீங்கள் விரும்புகிறீர்களா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (461, 'en', 'Are you happy to keep the policy even though it is not suitable for you?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (462, 'ms', 'Adakah anda gembira untuk mengekalkan polisi ini walaupun ia tidak sesuai untuk anda?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (463, 'zh', '即使这份保单不适合您，您是否仍愿意保留它？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (464, 'ta', 'இந்தப் பாலிசி உங்களுக்குப் பொருத்தமாக இல்லாவிட்டாலும் அதை வைத்துக்கொள்ள நீங்கள் விரும்புகிறீர்களா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (465, 'en', 'Have you terminated any policies in the past 12 months prior to this new policy purchase?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (466, 'ms', 'Adakah anda menamatkan sebarang polisi dalam tempoh 12 bulan sebelum pembelian polisi baharu ini?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (467, 'zh', '在购买这份新保单之前的12个月内，您是否终止过任何保单？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (468, 'ta', 'இந்தப் புதிய பாலிசியை வாங்குவதற்கு முந்தைய 12 மாதங்களில் ஏதேனும் பாலிசிகளை நிறுத்தியுள்ளீர்களா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (469, 'en', 'Have you terminated any policies in the past 12 months prior to this new policy purchase?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (470, 'ms', 'Adakah anda menamatkan sebarang polisi dalam tempoh 12 bulan sebelum pembelian polisi baharu ini?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (471, 'zh', '在购买这份新保单之前的12个月内，您是否终止过任何保单？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (472, 'ta', 'இந்தப் புதிய பாலிசியை வாங்குவதற்கு முந்தைய 12 மாதங்களில் ஏதேனும் பாலிசிகளை நிறுத்தியுள்ளீர்களா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (473, 'en', 'Was your agent informed of this termination?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (474, 'ms', 'Adakah ejen anda dimaklumkan tentang penamatan ini?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (475, 'zh', '您的代理人是否已被告知这次终止？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (233, 'en', 'Would you be comfortable for this call to be conducted in English?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (234, 'ms', 'Adakah anda selesa jika panggilan ini dijalankan dalam Bahasa Inggeris?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (235, 'zh', '您是否方便用英语进行这次通话？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (236, 'ta', 'இந்த அழைப்பை ஆங்கிலத்தில் நடத்துவது உங்களுக்கு வசதியாக இருக்குமா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (241, 'en', 'Which language would you prefer for this call: Mandarin, Bahasa Malay or Tamil?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (242, 'ms', 'Bahasa manakah yang anda lebih suka untuk panggilan ini: Mandarin, Bahasa Melayu atau Tamil?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (243, 'zh', '您希望用哪种语言进行这次通话：华语、马来语还是淡米尔语？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (244, 'ta', 'இந்த அழைப்புக்கு எந்த மொழியை விரும்புகிறீர்கள்: மாண்டரின், மலாய் அல்லது தமிழ்?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (313, 'en', 'Can I know if you received any additional premium support from the government before you bought this policy?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (314, 'ms', 'Boleh saya tahu sama ada anda menerima sebarang sokongan premium tambahan daripada kerajaan sebelum anda membeli polisi ini?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (315, 'zh', '请问您在购买这份保单之前，是否获得政府提供的任何额外保费补助？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (316, 'ta', 'இந்தப் பாலிசியை வாங்குவதற்கு முன் அரசாங்கத்திடமிருந்து ஏதேனும் கூடுதல் பிரீமிய உதவி பெற்றீர்களா என்று நான் தெரிந்துகொள்ளலாமா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (317, 'en', 'Can I know if you received any additional premium support from the government before you bought this policy?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (318, 'ms', 'Boleh saya tahu sama ada anda menerima sebarang sokongan premium tambahan daripada kerajaan sebelum anda membeli polisi ini?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (319, 'zh', '请问您在购买这份保单之前，是否获得政府提供的任何额外保费补助？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (320, 'ta', 'இந்தப் பாலிசியை வாங்குவதற்கு முன் அரசாங்கத்திடமிருந்து ஏதேனும் கூடுதல் பிரீமிய உதவி பெற்றீர்களா என்று நான் தெரிந்துகொள்ளலாமா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (321, 'en', 'Are you aware that your eligibility for financial assistance may be affected after buying the policy?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (322, 'ms', 'Adakah anda sedar bahawa kelayakan anda untuk bantuan kewangan mungkin terjejas selepas membeli polisi ini?');
