INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (328, 'ta', 'இந்தப் பாலிசியை வாங்கிய பிறகு நிதி உதவிக்கான உங்கள் தகுதி பாதிக்கப்படலாம் என்பது உங்களுக்குத் தெரியுமா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (329, 'en', 'Was any gift offered to you before the agent recommended the product?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (330, 'ms', 'Adakah sebarang hadiah ditawarkan kepada anda sebelum ejen mengesyorkan produk tersebut?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (331, 'zh', '在代理人推荐产品之前，是否有向您提供任何礼品？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (332, 'ta', 'முகவர் தயாரிப்பைப் பரிந்துரைப்பதற்கு முன் உங்களுக்கு ஏதேனும் பரிசு வழங்கப்பட்டதா?');
