INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (338, 'ms', 'Boleh saya tahu hadiah apakah yang ditawarkan kepada anda?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (339, 'zh', '请问向您提供的是什么礼品？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (340, 'ta', 'உங்களுக்கு என்ன பரிசு வழங்கப்பட்டது என்று நான் தெரிந்துகொள்ளலாமா?');
