INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (348, 'ta', 'இந்தப் பரிசு பற்றி முகவர் உங்களுக்கு எப்போது தெரிவித்தார்?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (349, 'en', 'When were you informed by the agent about this gift?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (350, 'ms', 'Bilakah ejen memaklumkan anda tentang hadiah ini?');
