INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (353, 'en', 'Were your financial situation, current financial plans, priorities and risk profile discussed with you before a suitable product was recommended?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (354, 'ms', 'Adakah keadaan kewangan, pelan kewangan semasa, keutamaan dan profil risiko anda dibincangkan dengan anda sebelum produk yang sesuai disyorkan?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (355, 'zh', '在向您推荐合适的产品之前，是否已与您讨论过您的财务状况、目前的财务规划、优先事项和风险属性？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (482, 'ms', 'Boleh saya tahu daripada syarikat insurans atau bank mana anda membeli polisi sebelumnya?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (483, 'zh', '请问您之前的保单是向哪家保险公司或银行购买的？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (484, 'ta', 'உங்கள் முந்தைய பாலிசியை எந்தக் காப்பீட்டு நிறுவனம் அல்லது வங்கியிடமிருந்து வாங்கினீர்கள் என்று நான் தெரிந்துகொள்ளலாமா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (485, 'en', 'Can I know which insurance company or bank you purchased the previous policy from?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (486, 'ms', 'Boleh saya tahu daripada syarikat insurans atau bank mana anda membeli polisi sebelumnya?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (487, 'zh', '请问您之前的保单是向哪家保险公司或银行购买的？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (488, 'ta', 'உங்கள் முந்தைய பாலிசியை எந்தக் காப்பீட்டு நிறுவனம் அல்லது வங்கியிடமிருந்து வாங்கினீர்கள் என்று நான் தெரிந்துகொள்ளலாமா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (489, 'en', 'What is the name of your previous policy, or the type of plan?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (490, 'ms', 'Apakah nama polisi anda sebelum ini, atau jenis pelannya?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (491, 'zh', '您之前的保单名称是什么？或是哪种类型的计划？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (492, 'ta', 'உங்கள் முந்தைய பாலிசியின் பெயர் என்ன? அல்லது திட்டத்தின் வகை என்ன?');
