INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (499, 'zh', '您是什么时候退保的？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (500, 'ta', 'அந்தப் பாலிசியை எப்போது சரணடையச் செய்தீர்கள்?');
