INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (507, 'zh', '您还记得那份保单的保障内容吗？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (508, 'ta', 'அந்தப் பாலிசியின் பலன்கள் உங்களுக்கு நினைவிருக்கிறதா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (513, 'en', 'Was your agent and his/her manager present at the sales meeting together with you?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (514, 'ms', 'Adakah ejen anda dan pengurusnya hadir bersama anda semasa mesyuarat jualan?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (515, 'zh', '您的代理人及其经理是否都与您一起出席了销售会面？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (516, 'ta', 'உங்கள் முகவரும் அவரது மேலாளரும் விற்பனைச் சந்திப்பில் உங்களுடன் சேர்ந்து இருந்தார்களா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (517, 'en', 'Can I know who is not present? Agent or Manager?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (518, 'ms', 'Boleh saya tahu siapa yang tidak hadir? Ejen atau Pengurus?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (519, 'zh', '请问谁没有出席？是代理人还是经理？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (520, 'ta', 'யார் இல்லை என்று நான் தெரிந்துகொள்ளலாமா? முகவரா அல்லது மேலாளரா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (521, 'en', 'Did you purchase this new policy to replace any of your existing policies?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (522, 'ms', 'Adakah anda membeli polisi baharu ini untuk menggantikan mana-mana polisi sedia ada anda?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (523, 'zh', '您购买这份新保单，是否是为了取代您现有的任何保单？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (524, 'ta', 'உங்களிடம் ஏற்கனவே உள்ள ஏதேனும் பாலிசிகளுக்குப் பதிலாக இந்தப் புதிய பாலிசியை வாங்கினீர்களா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (525, 'en', 'Did you purchase this new policy to replace any of your existing policies?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (526, 'ms', 'Adakah anda membeli polisi baharu ini untuk menggantikan mana-mana polisi sedia ada anda?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (527, 'zh', '您购买这份新保单，是否是为了取代您现有的任何保单？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (528, 'ta', 'உங்களிடம் ஏற்கனவே உள்ள ஏதேனும் பாலிசிகளுக்குப் பதிலாக இந்தப் புதிய பாலிசியை வாங்கினீர்களா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (529, 'en', 'Was your agent informed of this termination?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (530, 'ms', 'Adakah ejen anda dimaklumkan tentang penamatan ini?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (531, 'zh', '您的代理人是否已被告知这次终止？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (532, 'ta', 'இந்த நிறுத்தம் பற்றி உங்கள் முகவருக்குத் தெரிவிக்கப்பட்டதா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (533, 'en', 'Was your agent informed of this termination?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (534, 'ms', 'Adakah ejen anda dimaklumkan tentang penamatan ini?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (535, 'zh', '您的代理人是否已被告知这次终止？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (536, 'ta', 'இந்த நிறுத்தம் பற்றி உங்கள் முகவருக்குத் தெரிவிக்கப்பட்டதா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (537, 'en', 'Can I know which insurance company or bank you purchased the previous policy from?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (538, 'ms', 'Boleh saya tahu daripada syarikat insurans atau bank mana anda membeli polisi sebelumnya?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (539, 'zh', '请问您之前的保单是向哪家保险公司或银行购买的？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (590, 'ms', 'Terima kasih banyak atas masa anda. Adakah apa-apa maklum balas atau komen tambahan yang ingin anda kongsikan dengan AIA?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (591, 'zh', '非常感谢您抽出宝贵时间。您是否还有其他意见或反馈想与友邦分享？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (540, 'ta', 'உங்கள் முந்தைய பாலிசியை எந்தக் காப்பீட்டு நிறுவனம் அல்லது வங்கியிடமிருந்து வாங்கினீர்கள் என்று நான் தெரிந்துகொள்ளலாமா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (541, 'en', 'Can I know which insurance company or bank you purchased the previous policy from?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (542, 'ms', 'Boleh saya tahu daripada syarikat insurans atau bank mana anda membeli polisi sebelumnya?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (543, 'zh', '请问您之前的保单是向哪家保险公司或银行购买的？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (544, 'ta', 'உங்கள் முந்தைய பாலிசியை எந்தக் காப்பீட்டு நிறுவனம் அல்லது வங்கியிடமிருந்து வாங்கினீர்கள் என்று நான் தெரிந்துகொள்ளலாமா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (545, 'en', 'What is the name of your previous policy, or the type of plan?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (546, 'ms', 'Apakah nama polisi anda sebelum ini, atau jenis pelannya?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (547, 'zh', '您之前的保单名称是什么？或是哪种类型的计划？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (548, 'ta', 'உங்கள் முந்தைய பாலிசியின் பெயர் என்ன? அல்லது திட்டத்தின் வகை என்ன?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (549, 'en', 'What is the name of your previous policy, or the type of plan?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (550, 'ms', 'Apakah nama polisi anda sebelum ini, atau jenis pelannya?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (551, 'zh', '您之前的保单名称是什么？或是哪种类型的计划？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (552, 'ta', 'உங்கள் முந்தைய பாலிசியின் பெயர் என்ன? அல்லது திட்டத்தின் வகை என்ன?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (553, 'en', 'Do you remember the benefits of the policy?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (554, 'ms', 'Adakah anda ingat manfaat polisi tersebut?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (555, 'zh', '您还记得那份保单的保障内容吗？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (556, 'ta', 'அந்தப் பாலிசியின் பலன்கள் உங்களுக்கு நினைவிருக்கிறதா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (557, 'en', 'Do you remember the benefits of the policy?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (558, 'ms', 'Adakah anda ingat manfaat polisi tersebut?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (559, 'zh', '您还记得那份保单的保障内容吗？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (560, 'ta', 'அந்தப் பாலிசியின் பலன்கள் உங்களுக்கு நினைவிருக்கிறதா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (561, 'en', 'Have you been advised by your FSC to surrender your existing policies from other insurers or banks to buy this AIA policy?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (562, 'ms', 'Adakah anda dinasihatkan oleh FSC anda untuk menyerahkan polisi sedia ada anda daripada penanggung insurans atau bank lain bagi membeli polisi AIA ini?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (563, 'zh', '您的 FSC 是否曾建议您退保在其他保险公司或银行的现有保单，以购买这份友邦保单？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (564, 'ta', 'இந்த AIA பாலிசியை வாங்குவதற்காக, பிற காப்பீட்டாளர்கள் அல்லது வங்கிகளிடம் உள்ள உங்கள் தற்போதைய பாலிசிகளைச் சரணடையச் செய்யுமாறு உங்கள் FSC உங்களுக்கு அறிவுறுத்தினாரா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (565, 'en', 'Have you been advised by your FSC to surrender your existing policies from other insurers or banks to buy this AIA policy?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (566, 'ms', 'Adakah anda dinasihatkan oleh FSC anda untuk menyerahkan polisi sedia ada anda daripada penanggung insurans atau bank lain bagi membeli polisi AIA ini?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (567, 'zh', '您的 FSC 是否曾建议您退保在其他保险公司或银行的现有保单，以购买这份友邦保单？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (568, 'ta', 'இந்த AIA பாலிசியை வாங்குவதற்காக, பிற காப்பீட்டாளர்கள் அல்லது வங்கிகளிடம் உள்ள உங்கள் தற்போதைய பாலிசிகளைச் சரணடையச் செய்யுமாறு உங்கள் FSC உங்களுக்கு அறிவுறுத்தினாரா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (569, 'en', 'Were you satisfied with the services and overall experience with your AIA agent?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (570, 'ms', 'Adakah anda berpuas hati dengan perkhidmatan dan pengalaman keseluruhan anda bersama ejen AIA anda?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (571, 'zh', '您对友邦代理人的服务及整体体验是否满意？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (572, 'ta', 'உங்கள் AIA முகவரின் சேவைகள் மற்றும் ஒட்டுமொத்த அனுபவத்தில் நீங்கள் திருப்தி அடைந்தீர்களா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (573, 'en', 'Were you satisfied with the services and overall experience with your AIA agent?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (574, 'ms', 'Adakah anda berpuas hati dengan perkhidmatan dan pengalaman keseluruhan anda bersama ejen AIA anda?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (575, 'zh', '您对友邦代理人的服务及整体体验是否满意？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (576, 'ta', 'உங்கள் AIA முகவரின் சேவைகள் மற்றும் ஒட்டுமொத்த அனுபவத்தில் நீங்கள் திருப்தி அடைந்தீர்களா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (577, 'en', 'Can you share more details with me?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (578, 'ms', 'Boleh anda kongsikan butiran lanjut dengan saya?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (579, 'zh', '您能和我分享更多详情吗？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (580, 'ta', 'மேலும் விவரங்களை என்னுடன் பகிர்ந்துகொள்ள முடியுமா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (581, 'en', 'Can you share more details with me?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (582, 'ms', 'Boleh anda kongsikan butiran lanjut dengan saya?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (583, 'zh', '您能和我分享更多详情吗？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (584, 'ta', 'மேலும் விவரங்களை என்னுடன் பகிர்ந்துகொள்ள முடியுமா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (585, 'en', 'Thank you very much for your time. Is there any additional feedback or comment you would like to share with AIA?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (586, 'ms', 'Terima kasih banyak atas masa anda. Adakah apa-apa maklum balas atau komen tambahan yang ingin anda kongsikan dengan AIA?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (587, 'zh', '非常感谢您抽出宝贵时间。您是否还有其他意见或反馈想与友邦分享？');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (588, 'ta', 'உங்கள் நேரத்திற்கு மிக்க நன்றி. AIA-வுடன் பகிர்ந்துகொள்ள உங்களிடம் வேறு ஏதேனும் கருத்துகள் அல்லது கருத்துரைகள் உள்ளனவா?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (589, 'en', 'Thank you very much for your time. Is there any additional feedback or comment you would like to share with AIA?');
INSERT INTO strapi.components_shared_texts (id, locale, text) VALUES (592, 'ta', 'உங்கள் நேரத்திற்கு மிக்க நன்றி. AIA-வுடன் பகிர்ந்துகொள்ள உங்களிடம் வேறு ஏதேனும் கருத்துகள் அல்லது கருத்துரைகள் உள்ளனவா?');
